-- The Continuum 10 Vendors and Equipment remake plus the Preventive
-- Maintenance system (canon 0.29.0). Assets, tickets, recurring PM
-- schedules, and a seeded PM history. Signatures are hand typed by law
-- (no dropdown); seed signatures are whimsical and person-free (G-9).

CREATE TABLE equipment_assets (
  id TEXT PRIMARY KEY,
  serial TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  farm_code TEXT NOT NULL,
  notes TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  deleted_at TEXT,
  deleted_by TEXT,
  delete_reason TEXT
);

CREATE TABLE equipment_tickets (
  id TEXT PRIMARY KEY,
  asset_id TEXT NOT NULL,
  title TEXT NOT NULL,
  status TEXT NOT NULL,
  opened_by TEXT,
  closed_by TEXT,
  closed_at TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  deleted_at TEXT,
  deleted_by TEXT,
  delete_reason TEXT
);

CREATE TABLE equipment_pm_schedules (
  id TEXT PRIMARY KEY,
  asset_id TEXT NOT NULL,
  task TEXT NOT NULL,
  interval_days INTEGER NOT NULL,
  last_done TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  deleted_at TEXT,
  deleted_by TEXT
);

CREATE TABLE equipment_pm_logs (
  id TEXT PRIMARY KEY,
  asset_id TEXT NOT NULL,
  task TEXT NOT NULL,
  done_on TEXT NOT NULL,
  signed_by TEXT NOT NULL,
  notes TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  deleted_at TEXT,
  deleted_by TEXT
);

CREATE INDEX equipment_tickets_asset ON equipment_tickets (asset_id, status);
CREATE INDEX equipment_pm_schedules_asset ON equipment_pm_schedules (asset_id);
CREATE INDEX equipment_pm_logs_asset ON equipment_pm_logs (asset_id, done_on);




